-- ─────────────────────────────────────────────────────────────
--  BOOTY FLOW APP — CALCULATEUR NUTRITION (étape 4)
--  À lancer APRÈS supabase/formules.sql : Supabase › SQL Editor › New query › Run.
--  On peut le relancer sans risque : tes réglages déjà enregistrés ne sont pas écrasés.
--
--  Une seule ligne de réglages, modifiable dans l'espace coach › Nutrition App :
--    coefficients : dépense, activité, déficit / surplus, g/kg de protéines et de lipides, bonus des jours training…
--    aliments     : valeurs pour 100 g (poids cru ou cuit) et arrondi des quantités
--    journees     : les repas des journées types training et off (aliments et part de la journée)
--  Les besoins et les journées de chaque abonnée sont calculés dans l'app à partir de ces réglages.
-- ─────────────────────────────────────────────────────────────

create table if not exists public.nutrition_app (
  id int primary key default 1 check (id = 1),
  coefficients jsonb not null,
  aliments jsonb not null,
  journees jsonb not null,
  updated_at timestamptz not null default now()
);
alter table public.nutrition_app enable row level security;
drop policy if exists "nutrition app lecture" on public.nutrition_app;
create policy "nutrition app lecture" on public.nutrition_app for select using (public.est_coach() or public.acces_app());
drop policy if exists "nutrition app coach" on public.nutrition_app;
create policy "nutrition app coach" on public.nutrition_app for all using (public.est_coach()) with check (public.est_coach());

